import { DESCRIPTION, OPTION_FLAGS, SHORT_HELP_FLAG, HELP_FLAG, getUsage } from './spec.mjs';

export function formatHelp(programName) {
  const lines = [
    getUsage(programName),
    '',
    DESCRIPTION,
    '',
    'options:',
    `  ${SHORT_HELP_FLAG}, ${HELP_FLAG}  show this help message and exit`,
  ];

  for (const flag of OPTION_FLAGS) {
    lines.push(`  ${flag} ${flag.slice(2).toUpperCase()}`);
  }

  return `${lines.join('\n')}\n`;
}

export function formatExpectedArgument(flag) {
  return `argument ${flag}: expected one argument`;
}

export function formatIgnoredHelpArgument(value) {
  return `argument -h/--help: ignored explicit argument '${value}'`;
}

export function formatMissingRequired(flags) {
  return `the following arguments are required: ${flags.join(', ')}`;
}

export function formatUnrecognizedArguments(tokens) {
  return `unrecognized arguments: ${tokens.join(' ')}`;
}

export function formatAmbiguousOption(token, matches) {
  return `ambiguous option: ${token} could match ${matches.join(', ')}`;
}

export function formatError(programName, message) {
  return `${getUsage(programName)}\n${programName}: error: ${message}\n`;
}

