import { execFileSync } from 'node:child_process';

import { OPTION_KEYS } from '../cli/spec.mjs';

const EXECUTABLE_PATH = '/workspace/dataset/test19_executable';

function buildExecutableArgs(values) {
  const args = [];

  for (const key of OPTION_KEYS) {
    args.push(`--${key}`, values[key]);
  }

  return args;
}

function toText(output) {
  if (typeof output === 'string') {
    return output;
  }

  if (output === undefined || output === null) {
    return '';
  }

  return output.toString('utf8');
}

export function runTransformationChain(values) {
  return execFileSync(EXECUTABLE_PATH, buildExecutableArgs(values), {
    encoding: 'utf8',
  });
}

export function forwardExecutableFailure(error) {
  const stdout = toText(error.stdout);
  const stderr = toText(error.stderr);

  if (stdout.length > 0) {
    process.stdout.write(stdout);
  }

  if (stderr.length > 0) {
    process.stderr.write(stderr);
  }

  if (typeof error.status === 'number') {
    process.exit(error.status);
  }

  throw error;
}

