import { basename } from 'node:path';

import { formatError, formatHelp } from './lib/cli/messages.mjs';
import { parseArguments } from './lib/cli/parser.mjs';
import {
  forwardExecutableFailure,
  runTransformationChain,
} from './lib/runtime/executable.mjs';

function getProgramName() {
  if (process.argv[1]) {
    return basename(process.argv[1]);
  }

  return 'test19.mjs';
}

function main() {
  const programName = getProgramName();
  const result = parseArguments(process.argv.slice(2));

  if (result.kind === 'help') {
    process.stdout.write(formatHelp(programName));
    return;
  }

  if (result.kind === 'error') {
    process.stderr.write(formatError(programName, result.message));
    process.exit(2);
  }

  try {
    process.stdout.write(runTransformationChain(result.values));
  } catch (error) {
    forwardExecutableFailure(error);
  }
}

main();
